<?php

namespace App\Http\Controllers;

use App\Models\NotificationClear;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;

/**
 * Clears items from the notification bell.
 *
 * Clearing ONLY hides an item from the current user's bell. It never
 * deletes, completes, cancels, or edits the underlying Reminder
 * (or relief / complaint record).
 */
class NotificationClearController extends Controller
{
    /**
     * Keys are generated by layouts/app.blade.php and always look like
     * "bell:reminder:12:1790000000" or "bell:op:relief:5:2026-09-29".
     */
    private const KEY_PATTERN = '/^bell:[A-Za-z0-9:_\-]+$/';

    /**
     * Clear one notification from the bell.
     */
    public function clear(Request $request): JsonResponse
    {
        $validated = $request->validate([
            'key' => ['required', 'string', 'max:191', 'regex:' . self::KEY_PATTERN],
        ]);

        $this->remember($request->user()->id, [$validated['key']]);

        return response()->json([
            'ok' => true,
            'cleared' => 1,
        ]);
    }

    /**
     * Clear every notification currently shown in the bell.
     */
    public function clearAll(Request $request): JsonResponse
    {
        $validated = $request->validate([
            'keys' => ['required', 'array', 'min:1', 'max:200'],
            'keys.*' => ['required', 'string', 'max:191', 'regex:' . self::KEY_PATTERN],
        ]);

        $keys = array_values(array_unique($validated['keys']));

        $this->remember($request->user()->id, $keys);

        return response()->json([
            'ok' => true,
            'cleared' => count($keys),
        ]);
    }

    /**
     * Save the cleared keys for one user and prune very old entries.
     *
     * Bell items only ever cover today and tomorrow, so keys older than
     * 30 days can never match anything again.
     */
    private function remember(int $userId, array $keys): void
    {
        $now = now();

        $rows = array_map(
            static fn (string $key): array => [
                'user_id' => $userId,
                'notification_key' => $key,
                'cleared_at' => $now->toDateTimeString(),
            ],
            $keys
        );

        NotificationClear::upsert(
            $rows,
            ['user_id', 'notification_key'],
            ['cleared_at']
        );

        NotificationClear::query()
            ->where('user_id', $userId)
            ->where('cleared_at', '<', $now->copy()->subDays(30)->toDateTimeString())
            ->delete();
    }
}
